public class FileUploadServlet extends HttpServlet {
    // Secure file upload with input validation and sanitization
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String fileName = request.getParameter("fileName");
        // Validate filename - only allow alphanumeric, dots, underscores, and hyphens
        if (fileName != null && fileName.matches("^[a-zA-Z0-9._-]+$")) {
            // Use a fixed safe directory and canonical path to prevent directory traversal
            File uploadDir = new File("/safe/uploads/");
            File file = new File(uploadDir, fileName);
            // Resolve canonical path to prevent path traversal attacks
            if (file.getCanonicalPath().startsWith(uploadDir.getCanonicalPath())) {
                try (FileOutputStream fos = new FileOutputStream(file)) {
                    byte[] buffer = new byte[1024];
                    int bytesRead;
                    while ((bytesRead = request.getInputStream().read(buffer)) != -1) {
                        fos.write(buffer, 0, bytesRead);
                    }
                }
            } else {
                throw new SecurityException("Invalid file path");
            }
        } else {
            throw new SecurityException("Invalid filename");
        }
    }
}

